BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Tax-basis installment sale IRC 453 gain deferral
(2, 'Special Purpose Frameworks', 'Granite Building Supply sells a warehouse for $900,000 with $200,000 received at closing and the remaining $700,000 due in seven annual installments. The company prepares tax-basis financial statements and elects the installment method under IRC Section 453. How should the $700,000 unpaid balance be reported in Year 1?', '["Recognized as deferred revenue and amortized over seven years", "Reported as a receivable with gain deferred until payments are collected", "Excluded entirely because the cash has not yet been received", "Recognized in full as current-year revenue with a corresponding receivable"]'::jsonb, 1, 'Under IRC Section 453, the installment method defers gain recognition until cash is collected, but the receivable is still reported on the tax-basis balance sheet (AU-C 800; IRC §453). The gross profit ratio is applied to each payment as received to determine taxable income. Choice D is incorrect because it reflects GAAP treatment under ASC 610-20, which would recognize the full gain at sale rather than deferring it to collection periods.', 'medium', 2),

-- Q2: medium / L2 — Cash-basis payroll timing
(2, 'Special Purpose Frameworks', 'Northfield Marketing operates on the pure cash basis of accounting. December payroll of $85,000 covers work performed December 16–31. Paychecks are issued on January 5 of the following year. The controller asks how to report the December payroll on the year-end financial statements.', '["Record $85,000 as wages expense in December because the work was performed", "Record $42,500 in December and $42,500 in January to match the service period", "Record no wages expense in December because cash was not disbursed until January", "Record $85,000 as an accrued liability in December with expense recognized in January"]'::jsonb, 2, 'Under the pure cash basis, expenses are recognized only when cash is disbursed, regardless of when services were performed (AU-C 800.A2). The $85,000 payroll is recorded entirely in January when checks are issued. Choice A is incorrect because it reflects accrual-basis treatment under GAAP, which recognizes expense when incurred based on the matching principle, not when paid.', 'medium', 2),

-- Q3: easy / L1 — Cash-basis warranty obligations
(2, 'Special Purpose Frameworks', 'Under the pure cash basis of accounting, how are warranty obligations reported?', '["No warranty liability is recorded; warranty costs are expensed when paid", "Estimated warranty costs are accrued at the time of sale", "A contingent liability is disclosed in the notes but not recorded", "Warranty costs are capitalized as part of inventory cost"]'::jsonb, 0, 'Under the pure cash basis, no accruals or estimates are recorded (AU-C 800.A2). Warranty costs are recognized only when cash is disbursed to fulfill warranty claims. Choice B is incorrect because it reflects GAAP treatment under ASC 460, which requires accrual of estimated warranty obligations at the point of sale based on expected future costs.', 'easy', 1),

-- Q4: medium / L3 — Tax-basis charitable contribution IRC percentage limits
(2, 'Special Purpose Frameworks', 'Fieldstone Manufacturing prepares tax-basis financial statements and donates $180,000 to qualified charities during the year. Tax-basis taxable income before the charitable deduction is $600,000. Under the IRC, C corporations are limited to a 10% charitable contribution deduction. How should the donations be reported on the tax-basis income statement?', '["Deduct the full $180,000 as charitable contribution expense", "Deduct $60,000 and permanently disallow the remaining $120,000", "Report $180,000 as expense and add back $120,000 as a reconciling item", "Deduct $60,000 and carry forward the $120,000 excess to future years"]'::jsonb, 3, 'Under IRC Section 170(b)(2), C corporations may deduct charitable contributions up to 10% of taxable income ($600,000 × 10% = $60,000) with the excess carried forward five years (AU-C 800; IRC §170). On tax-basis statements, only the deductible $60,000 reduces current income; the $120,000 excess is a carryforward. Choice A is incorrect because it reflects GAAP treatment, which recognizes the full contribution as expense without percentage limitations.', 'medium', 3),

-- Q5: easy / L1 — Primary advantage of cash basis
(2, 'Special Purpose Frameworks', 'What is the primary advantage of the cash basis of accounting for small businesses?', '["It provides the most accurate measure of profitability", "It is the simplest to apply because it requires no accruals or estimates", "It is required by the IRC for all entities with revenue under $1 million", "It produces financial statements identical to GAAP for service businesses"]'::jsonb, 1, 'The cash basis is the simplest special purpose framework because it records transactions only when cash is received or paid, eliminating the need for accruals, estimates, and adjustments (AU-C 800.A2). This reduces preparation complexity and cost. Choice A is incorrect because cash-basis statements can be misleading, as they do not match revenues to the periods in which they are earned.', 'easy', 1),

-- Q6: medium / L3 — Cash-basis prepaid expense treatment
(2, 'Special Purpose Frameworks', 'Lakewood Consulting prepares pure cash-basis financial statements. On March 1, the firm pays $72,000 for a three-year professional liability insurance policy covering March Year 1 through February Year 4. Under GAAP, the firm would recognize $24,000 annually. How should the $72,000 payment be reported in Year 1?', '["$24,000 expense in Year 1 with $48,000 reported as a prepaid asset", "$20,000 expense covering March through December with the remainder deferred", "$72,000 expense in Year 1 because the full amount was disbursed", "$72,000 capitalized as an asset and amortized over three years"]'::jsonb, 2, 'Under the pure cash basis, expenses are recognized entirely when cash is disbursed, with no allocation to future periods (AU-C 800.A2). The full $72,000 is expensed in Year 1 regardless of the three-year coverage period. Choice A is incorrect because it reflects GAAP treatment under the matching principle, which allocates the cost over the benefit period as a prepaid expense.', 'medium', 3),

-- Q7: medium / L3 — Tax-basis like-kind exchange carryover basis
(2, 'Special Purpose Frameworks', 'Stonebridge Properties prepares tax-basis financial statements and completes a like-kind exchange under IRC Section 1031. The company exchanges a commercial building with a tax basis of $400,000 and fair value of $650,000 for a replacement property valued at $650,000. No boot is received. What is the replacement property''s basis on the tax-basis balance sheet?', '["$400,000 — the carryover basis from the relinquished property", "$650,000 — the fair value of the replacement property received", "$525,000 — the average of the tax basis and fair value", "$250,000 — the deferred gain recognized over the holding period"]'::jsonb, 0, 'Under IRC Section 1031, when no boot is received in a like-kind exchange, the replacement property takes the carryover basis of the relinquished property ($400,000), and the $250,000 gain is fully deferred (AU-C 800; IRC §1031(d)). On the tax-basis balance sheet, the asset is reported at $400,000. Choice B is incorrect because it reflects fair value measurement under GAAP, where assets acquired in an exchange are typically measured at fair value under ASC 845.', 'medium', 3),

-- Q8: medium / L3 — Modified cash basis inventory modification unacceptable
(2, 'Special Purpose Frameworks', 'Redwood Hardware prepares modified cash-basis financial statements. The company currently records depreciation on equipment and capitalizes long-term debt as its only modifications. The new CFO proposes recording inventory purchases as an asset and recognizing cost of goods sold when items are sold. Is this modification acceptable under the modified cash basis?', '["Acceptable because inventory adjustments relate to long-lived asset categories", "Acceptable because all modifications that improve accuracy are permitted", "Acceptable because inventory capitalization is required under the IRC", "Not acceptable because inventory accrual is a routine operating modification lacking substantial support"]'::jsonb, 3, 'Under AU-C Section 800.A22, modifications to the cash basis must have substantial support, generally limited to items with long-term effects such as depreciation, income taxes, and debt. Capitalizing inventory and recognizing cost of goods sold when sold is a routine operating accrual that would push the framework too close to GAAP. Choice A is incorrect because inventory is a current operating item, not a long-lived asset category.', 'medium', 3),

-- Q9: medium / L2 — Tax-basis C corp current tax only
(2, 'Special Purpose Frameworks', 'Hawthorn Industries is a C corporation preparing tax-basis financial statements. The company has $120,000 in temporary differences that would create a $25,200 deferred tax liability under ASC 740. The current federal income tax liability is $84,000. How should income taxes be reported on the tax-basis statements?', '["$84,000 current tax expense and $25,200 deferred tax expense totaling $109,200", "$84,000 current income tax expense only, with no deferred tax provision", "$109,200 total tax expense reported as a single line item", "$25,200 deferred tax expense only, as the current tax is a cash payment"]'::jsonb, 1, 'Under the tax basis of accounting, financial statements follow IRC measurement rules and do not recognize deferred tax assets or liabilities because the concept of temporary differences arises only under GAAP (AU-C 800; ASC 740). Only the current $84,000 income tax liability is reported. Choice A is incorrect because it reflects GAAP treatment under ASC 740, which requires recognition of both current and deferred tax provisions.', 'medium', 2),

-- Q10: easy / L1 — Cash-basis inventory purchases
(2, 'Special Purpose Frameworks', 'Under the pure cash basis of accounting, how are inventory purchases treated?', '["Expensed in full when cash is paid to the supplier", "Capitalized as an asset until sold to a customer", "Allocated between cost of goods sold and ending inventory", "Reported at the lower of cost or net realizable value"]'::jsonb, 0, 'Under the pure cash basis, all disbursements are expensed when cash is paid, with no capitalization of inventory or matching of costs to revenues (AU-C 800.A2). Inventory purchases are immediately recorded as expense upon payment. Choice B is incorrect because it reflects GAAP treatment, where inventory is capitalized as a current asset and recognized as cost of goods sold only when the related revenue is earned.', 'easy', 1),

-- Q11: hard / L4 — Multi-framework equipment expense comparison
(2, 'Special Purpose Frameworks', 'Apex Manufacturing purchases equipment for $300,000 cash on January 1, Year 1. The equipment has a 10-year useful life under GAAP (straight-line, no salvage) and qualifies for 5-year MACRS under the IRC (Year 1 rate: 20%). Apex also prepares cash-basis statements for internal use. Compare Year 1 equipment-related expense across three frameworks and identify the correct ranking from highest to lowest.', '["GAAP ($30,000) > Tax basis ($60,000) > Cash basis ($300,000)", "Tax basis ($60,000) > GAAP ($30,000) > Cash basis ($0)", "Cash basis ($300,000) > Tax basis ($60,000) > GAAP ($30,000)", "Cash basis ($300,000) > GAAP ($30,000) > Tax basis ($60,000)"]'::jsonb, 2, 'Under the pure cash basis, the full $300,000 is expensed when cash is disbursed (AU-C 800.A2). Under the tax basis, MACRS Year 1 at 20% produces $60,000 depreciation (IRC §168). Under GAAP, straight-line over 10 years yields $30,000 (ASC 360). Choice D is incorrect because it reverses the tax and GAAP amounts; MACRS produces higher early-year depreciation than straight-line due to its accelerated schedule.', 'hard', 4),

-- Q12: easy / L1 — Management selects the SPF
(2, 'Special Purpose Frameworks', 'Who is responsible for selecting the special purpose framework used to prepare an entity''s financial statements?', '["Management of the reporting entity", "The external auditor or CPA performing the engagement", "The AICPA Accounting Standards Board", "The entity''s primary lender or regulatory agency"]'::jsonb, 0, 'Under AU-C Section 800 and SSARS, management is responsible for selecting the financial reporting framework and preparing the financial statements in accordance with that framework. The auditor or CPA evaluates whether the statements are fairly presented but does not select the framework. Choice B is incorrect because the practitioner''s role is to report on the statements, not to choose the basis of accounting.', 'easy', 1),

-- Q13: medium / L2 — Tax-basis Section 174 R&D capitalization
(2, 'Special Purpose Frameworks', 'Palmer Biotech prepares tax-basis financial statements and incurs $500,000 in domestic research and development costs during Year 1. Under GAAP, the company would expense the full amount under ASC 730. Under the IRC as amended by the Tax Cuts and Jobs Act, how are domestic R&D costs reported on the tax-basis statements?', '["Expensed in full in Year 1, identical to GAAP treatment", "Capitalized indefinitely as an intangible asset with no amortization", "Deducted at 50% in Year 1 with the remainder deducted in Year 2", "Capitalized and amortized ratably over five years beginning in Year 1"]'::jsonb, 3, 'Under IRC Section 174, as amended by the TCJA effective for tax years beginning after 2021, domestic R&D expenditures must be capitalized and amortized over five years using the midpoint convention (AU-C 800; IRC §174). This creates a significant tax-to-GAAP difference. Choice A is incorrect because the IRC no longer permits immediate expensing of R&D costs, unlike GAAP under ASC 730.', 'medium', 2),

-- Q14: easy / L1 — Cash-basis statement of cash flows
(2, 'Special Purpose Frameworks', 'Under the pure cash basis of accounting, is a separate statement of cash flows typically required?', '["Yes, the statement of cash flows is required under all financial reporting frameworks", "No, because the income statement already reflects all cash receipts and disbursements", "Yes, but only the direct method is permitted under the cash basis", "No, because cash-basis entities are exempt from all secondary financial statements"]'::jsonb, 1, 'Under the pure cash basis, the income statement equivalent (statement of cash receipts and disbursements) inherently reports all cash inflows and outflows, making a separate statement of cash flows largely redundant (AU-C 800.A2). The cash-basis income statement effectively serves this purpose. Choice A is incorrect because GAAP requirements for a statement of cash flows do not automatically extend to special purpose frameworks.', 'easy', 1),

-- Q15: medium / L2 — SPF qualified opinion for framework departure
(2, 'Special Purpose Frameworks', 'Baxter Manufacturing prepares tax-basis financial statements. During the audit, the auditor discovers that the company recorded GAAP straight-line depreciation on all equipment instead of MACRS as required under the IRC. The departure is material but not pervasive. Under AU-C Section 800, what opinion should the auditor issue?', '["Unmodified opinion because the entity used a recognized depreciation method", "Disclaimer of opinion because the auditor cannot determine the correct tax amounts", "Qualified opinion because the statements contain a material departure from the tax-basis framework", "Unmodified opinion with an emphasis-of-matter paragraph noting the departure"]'::jsonb, 2, 'Under AU-C Section 800, the auditor evaluates whether SPF financial statements are fairly presented in accordance with the chosen framework. A material but not pervasive departure from the tax basis (using GAAP depreciation instead of MACRS) requires a qualified opinion (AU-C 800.14). Choice A is incorrect because conformity is measured against the elected SPF, not against any generally acceptable accounting method.', 'medium', 2),

-- Q16: medium / L2 — Tax-basis stock compensation timing
(2, 'Special Purpose Frameworks', 'Evergreen Technology prepares tax-basis financial statements. The company granted stock options to employees that vest over four years. Under ASC 718, the company would recognize $200,000 per year in compensation expense over the vesting period. Under the IRC, no options have been exercised in Year 1. How is stock compensation reported on the tax-basis income statement?', '["$200,000 compensation expense matching the GAAP vesting schedule", "$800,000 total compensation expense recognized immediately at grant date", "$200,000 expense with a deferred tax asset for the future deduction", "No compensation expense because no tax deduction has been triggered"]'::jsonb, 3, 'Under the tax basis, expenses follow IRC recognition rules. Stock option compensation is deductible only upon exercise, when the employee recognizes ordinary income (IRC §83(h); AU-C 800). Until exercise occurs, no tax deduction exists and no expense is reported on tax-basis statements. Choice A is incorrect because it reflects GAAP treatment under ASC 718, which requires expense recognition over the service period regardless of tax deductibility.', 'medium', 2),

-- Q17: easy / L2 — Cash-basis noncash barter transactions
(2, 'Special Purpose Frameworks', 'Willowbrook Design prepares pure cash-basis financial statements. A client pays for $15,000 in design services by transferring ownership of office furniture valued at $15,000 instead of paying cash. How should Willowbrook report this barter transaction?', '["No revenue is recorded because no cash was received", "$15,000 revenue and $15,000 furniture asset are both recorded", "$15,000 revenue is recorded because the furniture has equivalent value", "$7,500 revenue is recorded, reflecting a 50% discount for noncash payment"]'::jsonb, 0, 'Under the pure cash basis, revenue is recognized only when cash is received and expenses only when cash is paid (AU-C 800.A2). A barter exchange involves no cash and therefore results in no journal entry under the strict cash basis. Choice B is incorrect because it reflects accrual-basis treatment, where noncash exchanges of similar value would be recorded at fair value under ASC 845.', 'easy', 2),

-- Q18: hard / L3 — Regulatory SAP non-admitted assets
(2, 'Special Purpose Frameworks', 'Pinnacle Insurance Group prepares statutory accounting principles (SAP) financial statements for the state insurance department. Under SAP, certain assets are classified as non-admitted and excluded from the balance sheet. Pinnacle has $2,000,000 in office furniture, $500,000 in agent debit balances over 90 days past due, and $300,000 in goodwill. Under GAAP, all three items appear on the balance sheet. Under SAP, which items are classified as non-admitted assets?', '["Only the $300,000 in goodwill because intangibles lack cash realizability", "All three items — furniture, overdue agent balances, and goodwill — totaling $2,800,000", "The $500,000 in overdue agent balances and $300,000 in goodwill, but not the furniture", "None, because non-admitted asset rules apply only to investment securities"]'::jsonb, 1, 'Under statutory accounting principles, non-admitted assets are items that cannot be readily converted to cash to meet policyholder obligations. Furniture and equipment, overdue receivables past 90 days, and goodwill are all classified as non-admitted under SAP and excluded from the statutory balance sheet (AU-C 800; NAIC SAP). Choice C is incorrect because office furniture is also non-admitted under SAP due to its limited liquidity for meeting policyholder claims.', 'hard', 3),

-- Q19: hard / L4 — SPF framework change evaluation
(2, 'Special Purpose Frameworks', 'Riverside Consulting has prepared tax-basis financial statements for five years. The managing partner proposes switching to the modified cash basis starting in Year 6. The firm currently reports MACRS depreciation, Section 174 amortization, and installment sale receivables under the tax basis. The engagement partner must evaluate the reporting implications. Under the modified cash basis, depreciation and debt would remain, but installment receivables and Section 174 amortization would be inappropriate. Analyze the reporting implications.', '["No disclosure is needed because both frameworks are special purpose frameworks under AU-C 800", "The change is prohibited because entities cannot switch between special purpose frameworks", "The change requires disclosure of the nature and reason, with restatement of comparatives if practicable", "The change requires only a note identifying the new framework with no comparative restatement"]'::jsonb, 2, 'A change from one SPF to another is treated similarly to a change in accounting framework and requires disclosure of the nature and reason for the change under AU-C Section 800 and professional judgment. The auditor must consider whether comparative statements need restatement and whether the change is adequately explained (AU-C 708; AU-C 800). Choice B is incorrect because AU-C 800 does not prohibit framework changes; entities may select any recognized SPF.', 'hard', 4),

-- Q20: hard / L4 — Contractual basis framework completeness
(2, 'Special Purpose Frameworks', 'Meridian Joint Ventures enters a partnership agreement specifying that financial statements must: (1) report revenue when project milestones are certified, (2) capitalize equipment using straight-line depreciation over contract-specified lives, (3) exclude overhead allocations from project costs, and (4) measure partner equity based on capital account balances. The agreement is silent on debt measurement, contingencies, and related party transactions. The auditor is engaged under AU-C Section 800. Evaluate whether these provisions constitute a sufficient contractual basis.', '["Insufficient because the agreement must address every GAAP topic to qualify as an SPF", "Insufficient because the agreement does not specify the accounting treatment for debt", "Sufficient because the four provisions are internally consistent and the agreement is the source", "Sufficient as a contractual basis, but the auditor must apply professional judgment for items not addressed and ensure disclosures cover material omissions"]'::jsonb, 3, 'Under AU-C Section 800, contractual basis financial statements follow the specific provisions of the contract. When the agreement is silent on certain items, the auditor applies professional judgment and ensures that disclosures are sufficient to prevent the statements from being misleading (AU-C 800.14; AU-C 800.A24). Choice A is incorrect because a contractual basis need not replicate every GAAP topic — it provides a coherent framework for items it addresses with adequate disclosure for gaps.', 'hard', 4),

-- Q21: easy / L1 — SPF single financial statement
(2, 'Special Purpose Frameworks', 'Under a special purpose framework, can an entity present only a single financial statement rather than a full set?', '["No, all frameworks require a complete set of four financial statements", "Yes, an entity may present a single statement such as a statement of assets and liabilities", "Only if the entity is a sole proprietorship with less than $500,000 in revenue", "Only if the regulatory agency specifies a single-statement format"]'::jsonb, 1, 'Under AU-C Section 800 and SSARS, SPF financial statements are not required to include a complete set of statements. An entity may present a single financial statement appropriate to the framework and users'' needs (AU-C 800.02). Choice A is incorrect because the full-set requirement applies to GAAP financial statements, not necessarily to SPF presentations.', 'easy', 1),

-- Q22: easy / L1 — Tax-basis estimated warranty reserves
(2, 'Special Purpose Frameworks', 'Under the tax basis of accounting, how are estimated warranty reserves treated?', '["Not accrued — warranty costs are deducted only when actually paid or incurred", "Accrued at the point of sale based on historical warranty claim rates", "Recorded as a contingent liability with footnote disclosure", "Accrued using the same allowance method required under GAAP"]'::jsonb, 0, 'Under the IRC, estimated expenses such as warranty reserves do not meet the all-events test for deduction until economic performance occurs — meaning the warranty service is actually provided or the cost is paid (IRC §461(h); AU-C 800). On tax-basis statements, no estimated warranty liability is recorded. Choice B is incorrect because it reflects GAAP treatment under ASC 460, which requires accrual of estimated warranty costs at the point of sale.', 'easy', 1),

-- Q23: medium / L2 — Tax-basis accrual method vs GAAP differences
(2, 'Special Purpose Frameworks', 'Ironclad Distribution is a C corporation that uses the accrual method for both tax and GAAP purposes. The controller assumes the tax-basis and GAAP financial statements will be identical. Which difference persists even when a tax-basis entity uses the accrual method?', '["Timing of trade accounts payable recognition", "Classification of current versus noncurrent liabilities", "Revenue recognition criteria under IRC Section 451 versus ASC 606''s five-step model", "Presentation of the income statement in single-step versus multi-step format"]'::jsonb, 2, 'Even when both the IRC and GAAP use the accrual method, revenue recognition differs significantly. IRC Section 451 follows an earlier-of-income-received-or-accrued approach, while ASC 606 requires a five-step model with performance obligation analysis (AU-C 800; IRC §451; ASC 606). Choice A is incorrect because accrual-basis payables recognition timing is substantially similar under both frameworks.', 'medium', 2),

-- Q24: medium / L3 — Modified cash basis depreciation method flexibility
(2, 'Special Purpose Frameworks', 'Oakdale Landscaping prepares modified cash-basis financial statements and capitalizes equipment purchases. The owner asks the CPA whether the company must use straight-line depreciation or can elect MACRS accelerated depreciation for the capitalized equipment. How does the depreciation method choice affect the modified cash-basis classification?', '["Only straight-line depreciation is acceptable because MACRS is exclusively a tax-basis method", "Either method is acceptable because the modification is the recording of depreciation itself, not the specific method chosen", "MACRS is required because modified cash basis must follow IRC conventions", "Neither method is acceptable because depreciation is an unacceptable modification under modified cash basis"]'::jsonb, 1, 'Under AU-C Section 800.A22, the substantial support test for modified cash-basis modifications relates to whether depreciation is recorded, not to which specific method is used. Either straight-line or an accelerated method is acceptable as long as the modification is consistently applied and has substantial support. Choice A is incorrect because MACRS is not exclusive to the tax basis; entities may elect various depreciation systems under modified cash.', 'medium', 3),

-- Q25: hard / L4 — Regulatory statements expanded distribution impact
(2, 'Special Purpose Frameworks', 'Sentinel Mutual Insurance has historically prepared SAP financial statements solely for the state insurance department, with the auditor''s report including a restriction-on-use paragraph. The CEO now wants to distribute the same SAP statements to potential investors and post them on the company''s website. The SAP basis differs materially from GAAP. Under AU-C Section 800, what is the impact on the auditor''s reporting if distribution is expanded?', '["No change is needed because the auditor''s report already describes the regulatory basis", "The auditor must issue an adverse opinion because SAP differs materially from GAAP", "The auditor must add a second opinion paragraph on GAAP compliance alongside the SAP opinion", "The auditor must add or modify an emphasis-of-matter paragraph and may need to address the degree of GAAP departure for general-use distribution"]'::jsonb, 3, 'Under AU-C Section 800.15-17, when regulatory-basis financial statements that differ materially from GAAP are distributed beyond the regulatory agency (becoming general-use), the auditor''s report must include an emphasis-of-matter paragraph describing the SPF and may need to address the degree of departure from GAAP to prevent users from being misled (AU-C 800.17). Choice B is incorrect because the opinion is on compliance with the SPF, not GAAP; expanded distribution triggers enhanced reporting requirements, not an adverse opinion.', 'hard', 4),

-- Q26: medium / L3 — Modified cash basis deferred income tax modification
(2, 'Special Purpose Frameworks', 'Cedarbrook Plumbing prepares modified cash-basis financial statements and currently records only current income taxes owed. The CPA proposes adding recognition of deferred tax assets and liabilities arising from temporary timing differences. The engagement partner evaluates whether this modification has substantial support. Under the modified cash basis, is the accrual of deferred income taxes an acceptable modification?', '["Yes, because income tax accruals — both current and deferred — are modifications with substantial support", "No, because deferred taxes are purely a GAAP concept with no cash basis relevance", "Yes, but only if the deferred tax amounts are immaterial to the financial statements", "No, because modifications must relate to items that will result in cash payments within one year"]'::jsonb, 0, 'Under AU-C Section 800.A22, accrual of income taxes — including both current and deferred components — is a modification with substantial support because income taxes have long-term economic consequences that affect the entity beyond the current period. Choice B is incorrect because substantial support is not limited to items with immediate cash impact; long-term items such as income taxes, depreciation, and debt are specifically recognized as acceptable modifications.', 'medium', 3),

-- Q27: medium / L3 — Modified cash basis pension obligation evaluation
(2, 'Special Purpose Frameworks', 'Ferndale Machine Shop prepares modified cash-basis financial statements with depreciation and long-term debt as its current modifications. The owner establishes a defined benefit pension plan and asks the CPA whether the accrued pension obligation of $350,000 should be added as a modification. Evaluate whether recording the pension obligation is an acceptable modification under the modified cash basis.', '["Acceptable because pension obligations represent long-term liabilities similar to debt", "Not acceptable because pension accruals involve complex actuarial estimates that would push the framework too close to GAAP", "Acceptable only if the pension obligation exceeds 10% of total assets", "Not acceptable because any modification beyond depreciation and debt is automatically prohibited"]'::jsonb, 1, 'Under AU-C Section 800.A22, modifications must have substantial support — generally limited to items with straightforward long-term effects like depreciation, income taxes, and debt. Pension obligations require complex actuarial estimates and ASC 715 measurement that would overlay full GAAP methodology on the cash basis, moving the framework too close to accrual accounting. Choice A is incorrect because while pensions are long-term, the actuarial complexity distinguishes them from the simpler debt modifications that have established support.', 'medium', 3),

-- Q28: hard / L4 — SPF disclosure sufficiency across multiple material items
(2, 'Special Purpose Frameworks', 'Lancaster Real Estate Holdings prepares modified cash-basis financial statements. The entity has: (1) a $4 million mortgage maturing in 90 days with no refinancing arranged, (2) a $600,000 related party loan from the managing partner at below-market interest, (3) a pending environmental lawsuit with probable unfavorable outcome, and (4) a subsequent event where the primary tenant representing 60% of revenue declared bankruptcy after year-end. The engagement partner evaluates which GAAP-equivalent disclosures are required. Which items must be disclosed?', '["Only items (1) and (2), because going concern and related party disclosures are the only ones required under SSARS", "Only items (3) and (4), because contingencies and subsequent events are the only SPF-required disclosures", "All four items must be disclosed because each represents a material matter that could make the statements misleading if omitted", "None, because modified cash-basis financial statements are not required to include any disclosures beyond the framework description"]'::jsonb, 2, 'Under AU-C Section 800.A25, SPF financial statements must include informative disclosures similar to GAAP for items that would make the statements misleading if omitted — specifically going concern indicators, related party transactions, contingencies, and subsequent events. All four items are material and represent required GAAP-equivalent disclosures (AU-C 800; AR-C 80). Choice A is incorrect because it omits contingencies and subsequent events, which are equally important SPF disclosures.', 'hard', 4),

-- Q29: medium / L2 — Contractual basis departure from contract terms
(2, 'Special Purpose Frameworks', 'Highland Ventures prepares contractual-basis financial statements per a joint venture agreement. The agreement specifies that all equipment must be depreciated straight-line over five years. The CFO instead depreciates specialty equipment over 10 years, claiming the five-year life is unreasonably short. The departure is material. Under AU-C Section 800, what opinion should the auditor issue?', '["Accept the 10-year life because it more accurately reflects economic reality", "Withdraw from the engagement because the entity refuses to follow the contract", "Issue an unmodified opinion with an emphasis-of-matter paragraph explaining the departure", "Issue a qualified or adverse opinion for the departure from the contractual basis"]'::jsonb, 3, 'Under AU-C Section 800, the auditor measures fairness of presentation against the chosen framework. Departing from the contract''s specified five-year depreciation life is a material departure from the contractual basis, requiring a qualified or adverse opinion depending on pervasiveness (AU-C 800.14). Choice A is incorrect because under the contractual basis, the contract terms govern measurement, not management''s judgment about economic life.', 'medium', 2),

-- Q30: easy / L1 — Purpose of alternate titles on SPF statements
(2, 'Special Purpose Frameworks', 'What is the primary purpose of using different financial statement titles for SPF presentations compared to GAAP titles?', '["To comply with state licensing requirements for financial reporting", "To indicate that the statements have not been reviewed by a CPA", "To alert users that the statements are not prepared under GAAP", "To allow the entity to avoid an audit engagement"]'::jsonb, 2, 'Under AU-C Section 800 and SSARS, SPF financial statements must use titles that differ from GAAP titles (e.g., Statement of Assets and Liabilities — Tax Basis instead of Balance Sheet) to clearly communicate to users that the statements are prepared under a special purpose framework (AU-C 800.A17). Choice A is incorrect because the title requirement is a professional standard to prevent user confusion, not a state licensing requirement.', 'easy', 1)
;

COMMIT;
